  it("builds Claude Code's exact and prefix Skill options from tool input", () => {
    expect(build("Skill", undefined, { skill: "deploy prod" })).toMatchObject([
      { optionId: PERMISSION_OPTION_ID.allowOnce, name: "Yes" },
