        optionId: PERMISSION_OPTION_ID.allowSkillExact,
        name: "Yes, and don't ask again for deploy prod",
      },
      {
        optionId: PERMISSION_OPTION_ID.allowSkillPrefix,
        name: "Yes, and don't ask again for deploy:* commands",
      },
