import { describe, expect, it, vi } from "vitest";
import type { AcpSessionNotification } from "../acp-subagents.js";
import {
  announceNativeSubagent,
  finishNativeSubagent,
  NativeSubagent,
  NativeSubagentRuntime,
  NativeSubagentSession,
} from "../native-subagents.js";

function deferred(): { promise: Promise<void>; resolve: () => void } {
  let resolve!: () => void;
  const promise = new Promise<void>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

function child(overrides: Partial<NativeSubagent> = {}): NativeSubagent {
  return {
    sessionId: "child-1",
    parentSessionId: "root",
    parentToolUseId: "agent-tool",
    name: "Explore",
    task: "Inspect the project",
    ...overrides,
  };
}

function sessionWith(value: NativeSubagent): NativeSubagentSession {
  return {
    nativeSubagentsByTaskId: new Map([[value.sessionId, value]]),
    nativeSubagentTaskIdByToolUseId: new Map([[value.parentToolUseId!, value.sessionId]]),
    nativeSubagentParentByToolUseId: new Map(),
  };
}

function control(
  sessionUpdate: "tool_call" | "tool_call_update",
  status?: "pending" | "failed",
  parentToolUseId?: string,
): AcpSessionNotification {
  return {
    sessionId: "root",
    update: {
      sessionUpdate,
      toolCallId: "agent-tool",
      title: "Investigate failure",
      status,
      rawInput: { description: "Investigate failure", prompt: "Find the cause" },
      _meta: {
        claudeCode: { toolName: "Agent", subagent: true, parentToolUseId },
      },
    },
  } as AcpSessionNotification;
}

describe("NativeSubagentRuntime lifecycle", () => {
  it("publishes a raced spawn exactly once", async () => {
    const release = deferred();
    const published: AcpSessionNotification[] = [];
    const value = child();
    const publish = vi.fn(async (notification: AcpSessionNotification) => {
      published.push(notification);
      await release.promise;
    });

    const first = announceNativeSubagent(value, publish);
    const second = announceNativeSubagent(value, publish);

    await Promise.resolve();
    expect(publish).toHaveBeenCalledTimes(1);
    release.resolve();
    await Promise.all([first, second]);
    expect(published.map(({ update }) => update.sessionUpdate)).toEqual(["subagent_spawned"]);
  });

  it("publishes a raced terminal exactly once after the spawn", async () => {
    const releaseSpawn = deferred();
    const published: AcpSessionNotification[] = [];
    const value = child();
    const session = sessionWith(value);
    const publish = vi.fn(async (notification: AcpSessionNotification) => {
      published.push(notification);
      if (notification.update.sessionUpdate === "subagent_spawned") await releaseSpawn.promise;
    });

    const first = finishNativeSubagent(session, value.sessionId, "completed", publish);
    const second = finishNativeSubagent(session, value.sessionId, "cancelled", publish);
    releaseSpawn.resolve();
    await Promise.all([first, second]);

    expect(published.map(({ update }) => update.sessionUpdate)).toEqual([
      "subagent_spawned",
      "subagent_state_update",
    ]);
    expect(published[1]?.update).toMatchObject({ state: "completed" });
  });

  it("falls back to one ordinary failed tool call when no child ever starts", async () => {
    const runtime = new NativeSubagentRuntime(true, "root", {}, async () => {}, { log: () => {} });

    await expect(
      runtime.route(control("tool_call", "pending"), async () => {}),
    ).resolves.toBeNull();
    const fallback = await runtime.route(control("tool_call_update", "failed"), async () => {});

    expect(fallback).toMatchObject({
      sessionId: "root",
      update: {
        sessionUpdate: "tool_call",
        toolCallId: "agent-tool",
        title: "Investigate failure",
        status: "failed",
        _meta: { claudeCode: { toolName: "Agent" } },
      },
    });
    expect(
      (fallback?.update._meta?.claudeCode as Record<string, unknown>).subagent,
    ).toBeUndefined();
  });

  it("creates a schema-valid non-native failed tool call without a cached initial call", async () => {
    const runtime = new NativeSubagentRuntime(true, "root", {}, async () => {}, { log: () => {} });

    const fallback = await runtime.route(
      {
        sessionId: "root",
        update: {
          sessionUpdate: "tool_call_update",
          toolCallId: "agent-tool",
          status: "failed",
          _meta: { claudeCode: { toolName: "Agent", subagent: true } },
        },
      } as AcpSessionNotification,
      async () => {},
    );

    expect(fallback).toMatchObject({
      update: {
        sessionUpdate: "tool_call",
        toolCallId: "agent-tool",
        name: "Agent",
        title: "Agent",
        status: "failed",
        _meta: { claudeCode: { toolName: "Agent" } },
      },
    });
    expect(
      (fallback?.update._meta?.claudeCode as Record<string, unknown>).subagent,
    ).toBeUndefined();
  });

  it("clears failed-control identity and parent affinity before an id is reused", async () => {
    const outer = child({
      sessionId: "outer-child",
      parentToolUseId: "outer-tool",
      announced: true,
    });
    const session = sessionWith(outer);
    const published: AcpSessionNotification[] = [];
    const runtime = new NativeSubagentRuntime(
      true,
      "root",
      session,
      async (notification) => {
        published.push(notification);
      },
      { log: () => {} },
    );

    await runtime.route(control("tool_call", "pending", "outer-tool"), async () => {});
    await runtime.route(control("tool_call_update", "failed", "outer-tool"), async () => {});
    await runtime.taskStarted(
      {
        taskId: "reused-child",
        toolUseId: "agent-tool",
        subagentType: "Review",
        description: "Fresh identity",
      },
      async () => {},
    );
    await runtime.route(
      {
        ...control("tool_call", "pending"),
        update: {
          ...control("tool_call", "pending").update,
          rawInput: { description: "Fresh identity", prompt: "Review again" },
        },
      } as AcpSessionNotification,
      async () => {},
    );

    expect(published.at(-1)).toMatchObject({
      sessionId: "root",
      update: {
        sessionUpdate: "subagent_spawned",
        subagentSessionId: "reused-child",
        name: "Fresh identity",
      },
    });
  });

  it("discards unknown pending child updates during finishAll", async () => {
    const published: AcpSessionNotification[] = [];
    const delivered: AcpSessionNotification[] = [];
    const runtime = new NativeSubagentRuntime(
      true,
      "root",
      {},
      async (notification) => {
        published.push(notification);
      },
      { log: () => {} },
    );
    const pending = {
      sessionId: "root",
      update: {
        sessionUpdate: "agent_message_chunk",
        content: { type: "text", text: "stale" },
        _meta: { claudeCode: { parentToolUseId: "agent-tool" } },
      },
    } as AcpSessionNotification;

    await expect(
      runtime.route(pending, async (value) => {
        delivered.push(value);
      }),
    ).resolves.toBeNull();
    await runtime.finishAll("cancelled", async (value) => {
      delivered.push(value);
    });
    await runtime.taskStarted(
      {
        taskId: "child-1",
        toolUseId: "agent-tool",
        subagentType: "Explore",
        description: "New child",
      },
      async (value) => {
        delivered.push(value);
      },
    );
    await runtime.route(control("tool_call", "pending"), async (value) => {
      delivered.push(value);
    });

    expect(delivered).toEqual([]);
    expect(published).toHaveLength(1);
  });

  it("creates a distinct ACP lifecycle when the SDK restarts the same task id", async () => {
    const published: AcpSessionNotification[] = [];
    const runtime = new NativeSubagentRuntime(
      true,
      "root",
      {},
      async (notification) => {
        published.push(notification);
      },
      { log: () => {} },
    );
    const launch = (toolCallId: string) =>
      ({
        ...control("tool_call", "pending"),
        update: { ...control("tool_call", "pending").update, toolCallId },
      }) as AcpSessionNotification;
    const output = (parentToolUseId: string, text: string) =>
      ({
        sessionId: "root",
        update: {
          sessionUpdate: "agent_message_chunk",
          content: { type: "text", text },
          _meta: { claudeCode: { parentToolUseId } },
        },
      }) as AcpSessionNotification;

    await runtime.route(launch("launch-1"), async () => {});
    await runtime.taskStarted(
      {
        taskId: "worker-1",
        toolUseId: "launch-1",
        subagentType: "Explore",
        description: "First run",
      },
      async () => {},
    );
    await expect(runtime.route(output("launch-1", "first"), async () => {})).resolves.toMatchObject(
      { sessionId: "worker-1" },
    );
    await runtime.finishTask("worker-1", "completed", async () => {});

    await runtime.route(launch("launch-2"), async () => {});
    await runtime.taskStarted(
      {
        taskId: "worker-1",
        toolUseId: "launch-2",
        subagentType: "Explore",
        description: "Second run",
      },
      async () => {},
    );
    await expect(
      runtime.route(output("launch-2", "second"), async () => {}),
    ).resolves.toMatchObject({ sessionId: "worker-1:generation:2" });
    await runtime.finishTask("worker-1", "failed", async () => {}, "launch-1");
    expect(
      published.filter(({ update }) => update.sessionUpdate === "subagent_state_update"),
    ).toHaveLength(1);
    await expect(
      runtime.route(output("launch-2", "still running"), async () => {}),
    ).resolves.toMatchObject({ sessionId: "worker-1:generation:2" });
    await expect(runtime.route(output("launch-1", "late"), async () => {})).resolves.toBeNull();
    await runtime.finishTask("worker-1", "completed", async () => {}, "launch-2");

    const spawnedIds = published.flatMap(({ update }) =>
      update.sessionUpdate === "subagent_spawned" ? [update.subagentSessionId] : [],
    );
    const terminalIds = published.flatMap(({ update }) =>
      update.sessionUpdate === "subagent_state_update" ? [update.subagentSessionId] : [],
    );
    expect(spawnedIds).toEqual(["worker-1", "worker-1:generation:2"]);
    expect(terminalIds).toEqual(spawnedIds);
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { query, type ModelInfo, type Query } from "@anthropic-ai/claude-agent-sdk";
import { buildModelConfigOption, getAvailableModels } from "../session-model.js";

const OPUS: ModelInfo = {
  value: "opus[1m]",
  resolvedModel: "claude-opus-5[1m]",
  displayName: "Opus (1M context)",
  description: "Opus 5 with 1M context · Best for everyday, complex tasks",
};

describe("versioned model display names", () => {
  beforeEach(() => vi.stubEnv("ANTHROPIC_MODEL", undefined));
  afterEach(() => vi.unstubAllEnvs());

  it("adds standard-family versions and preserves model identity and recommendation", async () => {
    const models: ModelInfo[] = [
      { ...OPUS, value: "default", displayName: "Default (recommended)" },
      OPUS,
      { value: "sonnet[1m]", displayName: "Sonnet 5 (1M context)", description: "" },
      { value: "custom", displayName: "Custom Opus (1M context)", description: "" },
    ];
    const setModel = vi.fn();
    const state = await getAvailableModels(
      { setModel } as unknown as Query,
      models,
      models,
      { getSettings: () => ({}) },
      { log: vi.fn(), error: vi.fn() },
      false,
      "model-presentation-test",
    );

    expect(state.availableModels).toEqual(
      models.map((model) => ({
        modelId: model.value,
        name: model === OPUS ? "Opus 5" : model.displayName,
        description: model.description,
      })),
    );
    expect(buildModelConfigOption(state, models, true)).toMatchObject({
      currentValue: "opus[1m]",
      _meta: { jetbrains: { air: { recommendedValue: "opus[1m]" } } },
      options: expect.arrayContaining([
        { value: "opus[1m]", name: "Opus 5", description: OPUS.description },
      ]),
    });
    expect(OPUS.displayName).toBe("Opus (1M context)");
    expect(setModel).not.toHaveBeenCalled();
  });

  it("adds major and minor versions without changing custom or already-versioned names", async () => {
    const models: ModelInfo[] = [
      {
        value: "sonnet",
        resolvedModel: "claude-sonnet-5",
        displayName: "Sonnet",
        description: "Sonnet 5 · Efficient for routine tasks",
      },
      {
        value: "haiku",
        resolvedModel: "claude-haiku-4-5-20251001",
        displayName: "Claude Haiku",
        description: "Fast",
      },
      {
        value: "fable",
        resolvedModel: "claude-fable-5-1",
        displayName: "Fable",
        description: "Fable 5.1 · Creative model",
      },
      {
        value: "opus[1m]",
        resolvedModel: "claude-opus-5[1m]",
        displayName: "Opus 5 (1M context)",
        description: "",
      },
      { value: "custom", displayName: "My Sonnet", description: "" },
      { value: "future", displayName: "Haiku (1M context)", description: "" },
      { value: "custom-versioned", displayName: "Fable 5.1 (1M context)", description: "" },
    ];
    const state = await getAvailableModels(
      {} as Query,
      models,
      models,
      { getSettings: () => ({}) },
      { log: vi.fn(), error: vi.fn() },
      false,
      "model-presentation-test",
    );

    expect(state.availableModels.map((model) => model.name)).toEqual([
      "Sonnet 5",
      "Claude Haiku 4.5",
      "Fable 5.1",
      "Opus 5 (1M context)",
      "My Sonnet",
      "Haiku (1M context)",
      "Fable 5.1 (1M context)",
    ]);
  });

  it("only moves the context hint out of the name when the description retains it", async () => {
    const models: ModelInfo[] = [
      {
        value: "opus-described[1m]",
        resolvedModel: "claude-opus-5[1m]",
        displayName: "Opus 5 (1M context)",
        description: "Opus 5 with 1M context",
      },
      {
        value: "opus-undescribed[1m]",
        resolvedModel: "claude-opus-5[1m]",
        displayName: "Opus 5 (1M context)",
        description: "",
      },
      {
        value: "fable-undescribed[1m]",
        resolvedModel: "claude-fable-5-1[1m]",
        displayName: "Fable (1M context)",
        description: "",
      },
    ];
    const state = await getAvailableModels(
      {} as Query,
      models,
      models,
      { getSettings: () => ({}) },
      { log: vi.fn(), error: vi.fn() },
      false,
      "model-presentation-test",
    );

    expect(state.availableModels.map((model) => model.name)).toEqual([
      "Opus 5",
      "Opus 5 (1M context)",
      "Fable 5.1 (1M context)",
    ]);
  });

  it("keeps the suffix if another selectable model is already named Opus", async () => {
    const models = [OPUS, { ...OPUS, value: "opus", displayName: "Opus" }];
    const state = await getAvailableModels(
      {} as Query,
      models,
      models,
      { getSettings: () => ({}) },
      { log: vi.fn(), error: vi.fn() },
      false,
      "model-presentation-test",
    );
    expect(state.availableModels.map((model) => model.name)).toEqual(["Opus (1M context)", "Opus"]);
  });
});

// Account-dependent model availability requires the same authenticated environment
// as the adapter. No prompt is sent: inspect only the SDK initialization response.
it.skipIf(!process.env.RUN_INTEGRATION_TESTS)(
  "the real SDK exposes one named Opus with the expected context suffix",
  async () => {
    let finishInput!: () => void;
    const inputGate = new Promise<void>((resolve) => {
      finishInput = resolve;
    });
    // Keep stdin open for initialization without ever submitting a prompt.
    // eslint-disable-next-line require-yield
    async function* input() {
      await inputGate;
    }
    const abortController = new AbortController();
    const timeout = setTimeout(() => abortController.abort(), 25000);
    const q = query({ prompt: input(), options: { persistSession: false, abortController } });
    try {
      const { models } = await q.initializationResult();
      const opusModels = models.filter(
        (model) =>
          model.value !== "default" &&
          /\bopus\b/i.test(`${model.value} ${model.resolvedModel} ${model.displayName}`),
      );
      expect(opusModels).toHaveLength(1);
      expect(opusModels[0]).toMatchObject({
        value: "opus[1m]",
        displayName: "Opus (1M context)",
        resolvedModel: expect.stringMatching(/^claude-opus-.*\[1m\]$/),
        description: expect.stringContaining("1M context"),
      });
    } finally {
      clearTimeout(timeout);
      finishInput();
      q.close();
    }
  },
  30000,
);

import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";
import type { AcpClient, ClaudeAcpAgent as ClaudeAcpAgentType } from "../acp-agent.js";
import { makeMockQuery } from "./helpers.js";

const { querySpy } = vi.hoisted(() => ({
  querySpy: vi.fn(),
}));

vi.mock("@anthropic-ai/claude-agent-sdk", async () => {
  const actual = await vi.importActual<any>("@anthropic-ai/claude-agent-sdk");
  return {
    ...actual,
    query: querySpy,
  };
});

describe("ClaudeAcpAgent settings", () => {
  let tempDir: string;
  let originalClaudeConfigDir: string | undefined;

  function createMockClient(): AcpClient {
    return {
      sessionUpdate: async () => {},
      requestPermission: async () => ({ outcome: { outcome: "cancelled" } }),
      readTextFile: async () => ({ content: "" }),
      writeTextFile: async () => ({}),
    } as unknown as AcpClient;
  }

  function mockQuery() {
    let capturedOptions: any;
    const setModelSpy = vi.fn();
    querySpy.mockImplementation(({ options }: any) => {
      capturedOptions = options;
      return makeMockQuery({
        initializationResult: async () => ({
          models: [
            {
              value: "claude-sonnet-4-6",
              displayName: "Claude Sonnet 4.5",
              description: "Default",
            },
          ],
        }),
        setModel: setModelSpy,
      }) as any;
    });
    return { getCapturedOptions: () => capturedOptions, setModelSpy };
  }

  beforeEach(async () => {
    tempDir = await fs.promises.mkdtemp(path.join(os.tmpdir(), "acp-agent-settings-"));
    originalClaudeConfigDir = process.env.CLAUDE_CONFIG_DIR;
    process.env.CLAUDE_CONFIG_DIR = tempDir;
    querySpy.mockReset();
    vi.resetModules();
  });

  afterEach(async () => {
    if (originalClaudeConfigDir) {
      process.env.CLAUDE_CONFIG_DIR = originalClaudeConfigDir;
    } else {
      delete process.env.CLAUDE_CONFIG_DIR;
    }
    await fs.promises.rm(tempDir, { recursive: true, force: true });
  });

  it("uses permissions.defaultMode for new sessions", async () => {
    await fs.promises.writeFile(
      path.join(tempDir, "settings.json"),
      JSON.stringify({
        permissions: {
          defaultMode: "dontAsk",
        },
      }),
    );

    const projectDir = path.join(tempDir, "project");
    await fs.promises.mkdir(projectDir, { recursive: true });

    const { getCapturedOptions } = mockQuery();

    const { ClaudeAcpAgent } = await import("../acp-agent.js");
    const agent: ClaudeAcpAgentType = new ClaudeAcpAgent(createMockClient());

    const response = await (agent as any).createSession({
      cwd: projectDir,
      mcpServers: [],
      _meta: { disableBuiltInTools: true },
    });

    expect(getCapturedOptions().permissionMode).toBe("dontAsk");
    expect(getCapturedOptions().settingSources).toEqual(["user", "project", "local"]);
    expect(response.modes.currentModeId).toBe("default");
  }, 15_000);

  it.each([
    { recommended: false, setting: undefined, explicit: undefined, expected: "default" },
    { recommended: false, setting: "low", explicit: "high", expected: "high" },
    { recommended: true, setting: undefined, explicit: undefined, expected: "medium" },
    { recommended: true, setting: "high", explicit: undefined, expected: "high" },
    { recommended: true, setting: "high", explicit: "max", expected: "max" },
  ])(
    "initial effort reflects SDK state: %j",
    async ({ recommended, setting, explicit, expected }) => {
      await fs.promises.writeFile(
        path.join(tempDir, "settings.json"),
        JSON.stringify({ effortLevel: setting }),
      );
      const applyFlagSettings = vi.fn();
      querySpy.mockReturnValue(
        makeMockQuery({
          initializationResult: async () => ({
            models: [
              {
                value: "default",
                displayName: "Default",
                description: "",
                supportsEffort: true,
                supportedEffortLevels: ["low", "medium", "high", "max"],
              },
            ],
          }),
          applyFlagSettings,
        }),
      );
      const { ClaudeAcpAgent } = await import("../acp-agent.js");
      const agent = new ClaudeAcpAgent(createMockClient());
      if (recommended) {
        (agent as any).clientCapabilities = {
          _meta: { jetbrains: { air: { version: 1, capabilities: ["recommendedValue"] } } },
        };
      }
      const response = await (agent as any).createSession({
        cwd: tempDir,
        mcpServers: [],
        _meta: { disableBuiltInTools: true, claudeCode: { options: { effort: explicit } } },
      });
      expect(
        response.configOptions.find((option: any) => option.id === "effort").currentValue,
      ).toBe(expected);
      if (recommended) {
        expect(applyFlagSettings).toHaveBeenCalledWith({ effortLevel: expected });
      } else {
        expect(applyFlagSettings).not.toHaveBeenCalled();
      }
      expect(agent.sessions[response.sessionId].effortPinnedLevel).toBe(explicit);
      expect(agent.sessions[response.sessionId].appliedEffortLevel).toBe(
        recommended ? expected : explicit,
      );
    },
  );

  it("seeds effort from higher-priority programmatic model settings", async () => {
    await fs.promises.writeFile(
      path.join(tempDir, "settings.json"),
      JSON.stringify({
        effortLevel: "high",
        modelSettings: { "claude-sonnet-5[1m]": { effortLevel: "high" } },
      }),
    );
    const applyFlagSettings = vi.fn();
    querySpy.mockReturnValue(
      makeMockQuery({
        initializationResult: async () => ({
          models: [
            {
              value: "sonnet[1m]",
              resolvedModel: "claude-sonnet-5[1m]",
              displayName: "Sonnet",
              description: "",
              supportsEffort: true,
              supportedEffortLevels: ["low", "medium", "high"],
            },
          ],
        }),
        applyFlagSettings,
      }),
    );
    const { ClaudeAcpAgent } = await import("../acp-agent.js");
    const agent = new ClaudeAcpAgent(createMockClient());
    (agent as any).clientCapabilities = {
      _meta: { jetbrains: { air: { version: 1, capabilities: ["recommendedValue"] } } },
    };

    const response = await (agent as any).createSession({
      cwd: tempDir,
      mcpServers: [],
      _meta: {
        disableBuiltInTools: true,
        claudeCode: {
          options: {
            settings: {
              effortLevel: "medium",
              modelSettings: { "claude-sonnet-5-1m": { effortLevel: "low" } },
            },
          },
        },
      },
    });

    expect(response.configOptions.find((option: any) => option.id === "effort").currentValue).toBe(
      "low",
    );
    expect(applyFlagSettings).toHaveBeenCalledWith({ effortLevel: "low" });
    expect(agent.sessions[response.sessionId].effortSettingsOverride?.effortLevel).toBe("medium");
  });

  it("supports acceptEdits mode defaults", async () => {
    await fs.promises.writeFile(
      path.join(tempDir, "settings.json"),
      JSON.stringify({
        permissions: {
          defaultMode: "acceptEdits",
        },
      }),
    );

    const projectDir = path.join(tempDir, "project");
    await fs.promises.mkdir(projectDir, { recursive: true });

    const { getCapturedOptions } = mockQuery();

    const { ClaudeAcpAgent } = await import("../acp-agent.js");
    const agent: ClaudeAcpAgentType = new ClaudeAcpAgent(createMockClient());

    const response = await (agent as any).createSession({
      cwd: projectDir,
      mcpServers: [],
      _meta: { disableBuiltInTools: true },
    });

    expect(getCapturedOptions().permissionMode).toBe("acceptEdits");
    expect(response.modes.currentModeId).toBe("acceptEdits");
  });

  it("drops escalating defaultMode when it comes from project-tier settings", async () => {
    // bypassPermissions in .claude/settings.json (a repo-committed tier) is
    // filtered by the SDK's trust policy and clamps to 'default'.
    const projectDir = path.join(tempDir, "project");
    await fs.promises.mkdir(path.join(projectDir, ".claude"), { recursive: true });
    await fs.promises.writeFile(
      path.join(projectDir, ".claude", "settings.json"),
      JSON.stringify({ permissions: { defaultMode: "bypassPermissions" } }),
    );

    const { getCapturedOptions } = mockQuery();

    const { ClaudeAcpAgent } = await import("../acp-agent.js");
    const agent: ClaudeAcpAgentType = new ClaudeAcpAgent(createMockClient());

    const response = await (agent as any).createSession({
      cwd: projectDir,
      mcpServers: [],
      _meta: { disableBuiltInTools: true },
    });

    expect(getCapturedOptions().permissionMode).toBe("default");
    expect(response.modes.currentModeId).toBe("default");
  });

  it("honors the host opt-out from bypassPermissions", async () => {
    await fs.promises.writeFile(
      path.join(tempDir, "settings.json"),
      JSON.stringify({ permissions: { defaultMode: "bypassPermissions" } }),
    );
    const projectDir = path.join(tempDir, "project");
    await fs.promises.mkdir(projectDir, { recursive: true });

    const { getCapturedOptions } = mockQuery();

    const { ClaudeAcpAgent } = await import("../acp-agent.js");
    const agent: ClaudeAcpAgentType = new ClaudeAcpAgent(createMockClient());
    (agent as any).logger = { log: () => {}, error: () => {} };

    const response = await (agent as any).createSession({
      cwd: projectDir,
      mcpServers: [],
      _meta: {
        disableBuiltInTools: true,
        claudeCode: { options: { allowDangerouslySkipPermissions: false } },
      },
    });

    expect(getCapturedOptions().allowDangerouslySkipPermissions).toBe(false);
    expect(getCapturedOptions().permissionMode).toBe("default");
    expect(response.modes.currentModeId).toBe("default");
    expect(response.modes.availableModes.map((mode: { id: string }) => mode.id)).not.toContain(
      "bypassPermissions",
    );
  });

  it.each(["user", "project"] as const)(
    "honors permissions.disableBypassPermissionsMode from %s settings",
    async (tier) => {
      const projectDir = path.join(tempDir, "project");
      await fs.promises.mkdir(path.join(projectDir, ".claude"), { recursive: true });
      await fs.promises.writeFile(
        path.join(tempDir, "settings.json"),
        JSON.stringify({
          permissions: {
            defaultMode: "bypassPermissions",
            ...(tier === "user" ? { disableBypassPermissionsMode: "disable" } : {}),
          },
        }),
      );
      if (tier === "project") {
        await fs.promises.writeFile(
          path.join(projectDir, ".claude", "settings.json"),
          JSON.stringify({ permissions: { disableBypassPermissionsMode: "disable" } }),
        );
      }

      const { getCapturedOptions } = mockQuery();

      const { ClaudeAcpAgent } = await import("../acp-agent.js");
      const agent: ClaudeAcpAgentType = new ClaudeAcpAgent(createMockClient());
      (agent as any).logger = { log: () => {}, error: () => {} };

      const response = await (agent as any).createSession({
        cwd: projectDir,
        mcpServers: [],
        _meta: { disableBuiltInTools: true },
      });

      expect(getCapturedOptions().allowDangerouslySkipPermissions).toBe(false);
      expect(getCapturedOptions().permissionMode).toBe("default");
      expect(response.modes.currentModeId).toBe("default");
      expect(response.modes.availableModes.map((mode: { id: string }) => mode.id)).not.toContain(
        "bypassPermissions",
      );
    },
  );

  it("defaults to 'default' when no permissions.defaultMode is set", async () => {
    const projectDir = path.join(tempDir, "project");
    await fs.promises.mkdir(projectDir, { recursive: true });

    const { getCapturedOptions } = mockQuery();

    const { ClaudeAcpAgent } = await import("../acp-agent.js");
    const agent: ClaudeAcpAgentType = new ClaudeAcpAgent(createMockClient());

    const response = await (agent as any).createSession({
      cwd: projectDir,
      mcpServers: [],
      _meta: { disableBuiltInTools: true },
    });

    expect(getCapturedOptions().permissionMode).toBe("default");
    expect(response.modes.currentModeId).toBe("default");
  });

  it("falls back to 'default' when permissions.defaultMode is invalid", async () => {
    await fs.promises.writeFile(
      path.join(tempDir, "settings.json"),
      JSON.stringify({
        permissions: {
          defaultMode: "not-a-real-mode",
        },
      }),
    );

    const projectDir = path.join(tempDir, "project");
    await fs.promises.mkdir(projectDir, { recursive: true });

    const { getCapturedOptions } = mockQuery();

    const { ClaudeAcpAgent } = await import("../acp-agent.js");
    const agent: ClaudeAcpAgentType = new ClaudeAcpAgent(createMockClient());

    const response = await (agent as any).createSession({
      cwd: projectDir,
      mcpServers: [],
      _meta: { disableBuiltInTools: true },
    });

    // Bad mode is ignored at the usage site; session creation must not throw.
    expect(getCapturedOptions().permissionMode).toBe("default");
    expect(response.modes.currentModeId).toBe("default");
  });

  it("ignores model from settings when it is not a string", async () => {
    await fs.promises.writeFile(
      path.join(tempDir, "settings.json"),
      JSON.stringify({
        model: 123,
