      const { ClaudeAcpAgent } = await import("../acp-agent.js");
      const agent: ClaudeAcpAgentType = new ClaudeAcpAgent(createMockClient());

      const response = await (agent as any).createSession({
        cwd: projectDir,
        mcpServers: [],
        _meta: { disableBuiltInTools: true },
      });

      const modelOption = response.configOptions.find((o: any) => o.id === "model");
      expect(modelOption.options.map((o: any) => o.value)).toEqual([
        "default",
        "global.anthropic.claude-opus-4-6-v1[1m]",
        "global.anthropic.claude-sonnet-4-6[1m]",
      ]);
      // The allowlist synthesized the overridden ID (the SDK only surfaced the
      // `opus` alias), so the adapter syncs the provider ID via setModel — never
      // the raw alias that Bedrock would reject.
      expect(setModelSpy).toHaveBeenCalledWith("global.anthropic.claude-opus-4-6-v1[1m]");
      expect(modelOption.currentValue).toBe("global.anthropic.claude-opus-4-6-v1[1m]");
    });
  });

  it("resolves model aliases like opus[1m] to the correct model", async () => {
    await fs.promises.writeFile(
      path.join(tempDir, "settings.json"),
      JSON.stringify({
        model: "opus[1m]",
      }),
    );

    const projectDir = path.join(tempDir, "project");
    await fs.promises.mkdir(projectDir, { recursive: true });

    const setModelSpy = vi.fn();
    querySpy.mockImplementation(({ options: _options }: any) => {
      return makeMockQuery({
        initializationResult: async () => ({
          models: [
            {
              value: "claude-opus-4-6",
              displayName: "Claude Opus 4.6",
              description: "Base",
            },
            {
              value: "claude-opus-4-6-1m",
              displayName: "Claude Opus 4.6 (1M)",
              description: "Long context",
            },
          ],
        }),
        setModel: setModelSpy,
      }) as any;
    });

    const { ClaudeAcpAgent } = await import("../acp-agent.js");
    const agent: ClaudeAcpAgentType = new ClaudeAcpAgent(createMockClient());

    const response = await (agent as any).createSession({
      cwd: projectDir,
      mcpServers: [],
      _meta: { disableBuiltInTools: true },
    });

    expect(setModelSpy).toHaveBeenCalledWith("claude-opus-4-6-1m");
    expect(response.configOptions?.find((o: any) => o.id === "model")?.currentValue).toBe(
      "claude-opus-4-6-1m",
    );
  });

  it("skips the initial setModel when the resolved value matches the SDK's model list verbatim", async () => {
    // Covers the launcher case from PR #646: the launcher bakes the model into
    // ANTHROPIC_MODEL, the SDK already starts on that model, and a second
    // setModel call would be a redundant round-trip (and on some launcher
    // setups, more fragile than launch-time selection).
    const originalEnv = process.env.ANTHROPIC_MODEL;
    process.env.ANTHROPIC_MODEL = "claude-opus-4-6";

    const projectDir = path.join(tempDir, "project");
    await fs.promises.mkdir(projectDir, { recursive: true });

    const setModelSpy = vi.fn();
    querySpy.mockImplementation(() => {
      return makeMockQuery({
        initializationResult: async () => ({
          models: [
            { value: "default", displayName: "Default", description: "" },
            { value: "claude-sonnet-4-6", displayName: "Claude Sonnet 4.6", description: "" },
            { value: "claude-opus-4-6", displayName: "Claude Opus 4.6", description: "" },
          ],
        }),
        setModel: setModelSpy,
      }) as any;
    });

    try {
      const { ClaudeAcpAgent } = await import("../acp-agent.js");
      const agent: ClaudeAcpAgentType = new ClaudeAcpAgent(createMockClient());

      const response = await (agent as any).createSession({
        cwd: projectDir,
        mcpServers: [],
        _meta: { disableBuiltInTools: true },
      });

      expect(setModelSpy).not.toHaveBeenCalled();
      expect(response.configOptions?.find((o: any) => o.id === "model")?.currentValue).toBe(
        "claude-opus-4-6",
      );
    } finally {
      if (originalEnv === undefined) {
        delete process.env.ANTHROPIC_MODEL;
      } else {
        process.env.ANTHROPIC_MODEL = originalEnv;
      }
    }
  });

  it("still calls setModel when the allowlist synthesizes a value the SDK has not surfaced", async () => {
    // The allowlist may rewrite a model's `value` to the user's literal ID
    // (e.g., `claude-haiku-4-5`) even when the SDK only exposed an alias
    // (`haiku`). In that case the SDK has not independently arrived at the
    // user's preferred ID, so we must sync via setModel.
    await fs.promises.writeFile(
      path.join(tempDir, "settings.json"),
      JSON.stringify({
        availableModels: ["claude-haiku-4-5"],
        model: "claude-haiku-4-5",
      }),
    );

    const projectDir = path.join(tempDir, "project");
    await fs.promises.mkdir(projectDir, { recursive: true });

    const setModelSpy = vi.fn();
    querySpy.mockImplementation(() => {
      return makeMockQuery({
        initializationResult: async () => ({
          models: [
            { value: "default", displayName: "Default", description: "" },
            { value: "haiku", displayName: "Haiku", description: "Fast" },
          ],
        }),
        setModel: setModelSpy,
      }) as any;
    });

    const { ClaudeAcpAgent } = await import("../acp-agent.js");
    const agent: ClaudeAcpAgentType = new ClaudeAcpAgent(createMockClient());

    const response = await (agent as any).createSession({
      cwd: projectDir,
      mcpServers: [],
      _meta: { disableBuiltInTools: true },
    });

    expect(setModelSpy).toHaveBeenCalledWith("claude-haiku-4-5");
    expect(response.configOptions?.find((o: any) => o.id === "model")?.currentValue).toBe(
      "claude-haiku-4-5",
    );
  });
});

import { describe, it, expect } from "vitest";
import type {
  CreateElicitationRequest,
  CreateElicitationResponse,
  EnumOption,
} from "@agentclientprotocol/sdk";
import type { ElicitationRequest } from "@anthropic-ai/claude-agent-sdk";
import {
  applyAskElicitationResponse,
  askUserQuestionsToCreateRequest,
  AskUserQuestion,
  createElicitationResponseToElicitResult,
  extractAskUserQuestions,
  extractRefusalFallbackPrompt,
  mcpElicitationToCreateRequest,
  refusalFallbackResultFromResponse,
  refusalFallbackToCreateRequest,
} from "../elicitation.js";

const SESSION_ID = "session-1";

/**
 * Build a question matching the SDK's (strict) AskUserQuestion schema while
 * keeping test sites terse. Option descriptions default to "" (the tool always
 * provides one); pass a description to exercise the enum option's description.
 */
function mkQuestion(
  question: string,
  options: Array<{ label: string; description?: string; preview?: string }>,
  opts: { header?: string; multiSelect?: boolean } = {},
): AskUserQuestion {
  return {
    question,
    header: opts.header ?? "",
    multiSelect: opts.multiSelect ?? false,
    options: options.map((o) => ({
      label: o.label,
      description: o.description ?? "",
      ...(o.preview ? { preview: o.preview } : {}),
    })),
  } as AskUserQuestion;
}

describe("mcpElicitationToCreateRequest", () => {
  it("maps a form-mode request, defaulting the schema type to object", () => {
    const request: ElicitationRequest = {
      serverName: "server",
      message: "Need your name",
      mode: "form",
      requestedSchema: { properties: { name: { type: "string" } } },
    };

    const result = mcpElicitationToCreateRequest(request, SESSION_ID);

    expect(result).toEqual({
      mode: "form",
      sessionId: SESSION_ID,
      message: "Need your name",
      requestedSchema: { type: "object", properties: { name: { type: "string" } } },
    });
  });

  it("maps a url-mode request and preserves the elicitation id", () => {
    const request: ElicitationRequest = {
      serverName: "server",
      message: "Authorize",
      mode: "url",
      url: "https://example.com/auth",
      elicitationId: "el-123",
    };

    expect(mcpElicitationToCreateRequest(request, SESSION_ID)).toEqual({
      mode: "url",
      sessionId: SESSION_ID,
      message: "Authorize",
      url: "https://example.com/auth",
      elicitationId: "el-123",
    });
  });

  it("generates an elicitation id when a url request omits one", () => {
    const request: ElicitationRequest = {
      serverName: "server",
      message: "Authorize",
      mode: "url",
      url: "https://example.com/auth",
    };

    const result = mcpElicitationToCreateRequest(request, SESSION_ID);
    expect(result?.mode).toBe("url");
    expect((result as { elicitationId: string }).elicitationId).toMatch(/.+/);
  });

  it("returns null for a url request with no url", () => {
    const request: ElicitationRequest = {
      serverName: "server",
      message: "Authorize",
      mode: "url",
    };

    expect(mcpElicitationToCreateRequest(request, SESSION_ID)).toBeNull();
  });
});

