describe("refusalFallbackToCreateRequest", () => {
  const prompt = {
    originalModel: "claude-fable-5",
    fallbackModel: "claude-opus-4-8",
    apiRefusalCategory: "cyber" as string | null,
  };

  it("builds a single-choice form whose enum consts are the dialog's wire results", () => {
    const request = refusalFallbackToCreateRequest(prompt, SESSION_ID) as Extract<
      CreateElicitationRequest,
      { mode: "form" }
    >;
    expect(request.mode).toBe("form");
    expect(request).toMatchObject({ sessionId: SESSION_ID });
    expect(request.message).toContain("claude-fable-5");
    expect(request.message).toContain("(cyber)");
    expect(request.message).toContain("claude-opus-4-8");

    const choice = request.requestedSchema.properties?.choice as {
      type: string;
      oneOf: Array<{ const: string; title: string; description?: string }>;
    };
    expect(choice.type).toBe("string");
    expect(choice.oneOf.map((o) => o.const)).toEqual(["retry_fallback", "cancelled"]);
    expect(choice.oneOf[0].title).toContain("claude-opus-4-8");
    // Each option explains its consequence in the description field.
    expect(choice.oneOf[0].description).toContain("claude-opus-4-8");
    expect(choice.oneOf[1].description).toBeTruthy();
  });

  it("omits the category marker and appends guidance when provided", () => {
    const request = refusalFallbackToCreateRequest(
      { ...prompt, apiRefusalCategory: null, guidanceText: "Consider rephrasing." },
      SESSION_ID,
    );
    expect(request.message).not.toContain("(");
    expect(request.message).toContain("Consider rephrasing.");
  });
});

describe("refusalFallbackResultFromResponse", () => {
  it("maps an accepted retry choice to retry_fallback", () => {
    const response = {
      action: "accept",
      content: { choice: "retry_fallback" },
    } as CreateElicitationResponse;
    expect(refusalFallbackResultFromResponse(response)).toBe("retry_fallback");
  });

  it("keeps the refusal for every other outcome", () => {
    const cases = [
      { action: "accept", content: { choice: "cancelled" } },
      { action: "accept", content: {} },
      { action: "accept", content: { choice: "something-new" } },
      { action: "accept" },
      { action: "decline" },
      { action: "cancel" },
    ] as CreateElicitationResponse[];
    for (const response of cases) {
      expect(refusalFallbackResultFromResponse(response)).toBe("cancelled");
    }
  });
});

export const CONTEXT_COMPACTION_META_KEY = "contextCompaction";
export const CONTEXT_COMPACTION_META_VERSION = 1;

export type ContextCompactionTrigger = "manual" | "automatic";

export interface ContextCompactionMetadata {
  version: typeof CONTEXT_COMPACTION_META_VERSION;
  trigger?: ContextCompactionTrigger;
  preTokens?: number;
  postTokens?: number;
  durationMs?: number;
  error?: string;
}

/**
 * Provider-neutral metadata for a synthetic ACP context-compaction tool call.
 * The standard toolCallId and status fields own lifecycle identity and phase;
 * this extension carries only compaction-specific facts.
 */
export function createContextCompactionMeta(
  metadata: Omit<ContextCompactionMetadata, "version"> = {},
): Record<typeof CONTEXT_COMPACTION_META_KEY, ContextCompactionMetadata> {
  return {
    [CONTEXT_COMPACTION_META_KEY]: {
      version: CONTEXT_COMPACTION_META_VERSION,
      ...metadata,
    },
  };
}

import { ClientCapabilities, SessionNotification } from "@agentclientprotocol/sdk";
import {
  ContextCompactionMetadata,
  createContextCompactionMeta,
} from "./context-compaction-meta.js";

type CompactionStatus = "completed" | "failed";
type TerminalStatus = CompactionStatus | "cancelled";

/**
 * How compaction reaches the client.
 *
 * - `compaction_update`: the ACP session-compaction contract (ID-addressed
 *   `compaction_update` / `compaction_summary_chunk`), used when the v1 client
 *   advertises `clientCapabilities.session.compaction`.
 * - `tool_call`: the legacy synthetic "Compact conversation" tool call, kept
 *   for clients that do not advertise the capability.
 */
export type CompactionPresentation = "tool_call" | "compaction_update";

type CompactionState = {
  /** Doubles as the toolCallId under the legacy presentation. */
  compactionId: string;
  terminalStatus?: TerminalStatus;
  heartbeatSent: boolean;
  /** User-displayable summary reported by the PostCompact hook. While the
   *  compaction is in progress it awaits the terminal update; on a `completed`
   *  state it has been sent. */
  summary?: string;
};

type SendUpdate = (notification: SessionNotification) => Promise<void>;

export type ContextCompactionLifecycleOptions = {
  sessionId: string;
  presentation?: CompactionPresentation;
  /** Receives failures of the send that must not propagate: the turn-boundary
   *  `cancelled` terminal. */
  logError?: (message: string, error: unknown) => void;
};

export function clientSupportsCompactionUpdates(capabilities?: ClientCapabilities | null): boolean {
  const compaction = capabilities?.session?.compaction;
  return typeof compaction === "object" && compaction !== null && !Array.isArray(compaction);
}

/** Tags on their own line, as the model emits them; a summary that merely
 *  quotes `<summary>` mid-sentence must not be truncated at the mention. */
const SUMMARY_OPEN_LINE = /^[ \t]*<summary>[ \t]*\r?\n/gim;
const SUMMARY_CLOSE_LINE = /^[ \t]*<\/summary>[ \t]*$/gim;
/** The model's private reasoning block that precedes the summary; stripped
 *  first so a `<summary>` it merely mentions cannot anchor the summary span,
 *  and even when the summary tags themselves are missing. Own-line tags
 *  anywhere; inline tags only as a leading block, since a summary body may
 *  quote both tag names. */
const ANALYSIS_BLOCKS = [
  /^[ \t]*<analysis>[ \t]*\r?\n[\s\S]*?\n[ \t]*<\/analysis>[ \t]*$/gim,
  /^\s*<analysis>[\s\S]*?<\/analysis>/i,
];
/** The framing Claude Code wraps around the retained summary when it persists
 *  it as the post-compaction user message. */
const CONTINUATION_PREAMBLE = /^\s*This session is being continued from a previous conversation/i;
const PERSISTED_PREAMBLE =
  /^\s*This session is being continued from a previous conversation[^\n]*\n+Summary:[ \t]*\r?\n/;
const PERSISTED_TRAILERS = [
  /\n+If you need specific details from before compaction[\s\S]*$/,
  /\n+(?:Please )?[Cc]ontinue the conversation from where it left (?:it )?off[\s\S]*$/,
];

/**
 * Reduce Claude's compaction output to the user-displayable summary.
 *
 * The PostCompact hook reports the model's raw output, which wraps the
 * summary in `<summary>` tags (often preceded by an `<analysis>` block). The
 * persisted transcript instead frames the same summary with continuation
 * instructions for the model. Neither framing belongs in the ACP `summary`,
 * and a continuation prompt whose framing is not recognized yields no summary
 * at all rather than model-facing instructions.
 */
export function compactionSummaryText(raw: string): string | undefined {
  let text = raw;
  for (const block of ANALYSIS_BLOCKS) {
    text = text.replace(block, "");
  }
  const tagged = taggedSummary(text);
  if (tagged !== undefined) {
    text = tagged;
  } else if (CONTINUATION_PREAMBLE.test(text)) {
    const body = text.replace(PERSISTED_PREAMBLE, "");
    if (body === text) return undefined;
    text = body;
    for (const trailer of PERSISTED_TRAILERS) {
      text = text.replace(trailer, "");
    }
  }
  text = text.trim();
  return text.length > 0 ? text : undefined;
}

function taggedSummary(raw: string): string | undefined {
  const close = [...raw.matchAll(SUMMARY_CLOSE_LINE)].at(-1);
  if (close?.index !== undefined) {
    const open = [...raw.slice(0, close.index).matchAll(SUMMARY_OPEN_LINE)].at(-1);
    if (open?.index !== undefined) {
      return raw.slice(open.index + open[0].length, close.index);
    }
  }
  // Inline tags: the widest span, so a quoted `</summary>` inside the body
  // does not end it early. Plain index scans keep an unterminated tag linear.
  const openInline = raw.search(/<summary>/i);
  const closeInline = raw.toLowerCase().lastIndexOf("</summary>");
  if (openInline >= 0 && closeInline > openInline) {
    return raw.slice(openInline + "<summary>".length, closeInline);
  }
  return undefined;
}

/** True for the post-compaction user message Claude Code persists (and
 *  `getSessionMessages` returns) with the summary of the dropped history. */
export function isCompactSummaryMessage(message: unknown): boolean {
  return (
    typeof message === "object" &&
    message !== null &&
    (message as { type?: unknown }).type === "user" &&
    (message as { isCompactSummary?: unknown }).isCompactSummary === true
  );
}

/**
 * Translates Claude's compaction signals into one idempotent ACP lifecycle.
 *
 * The SDK can duplicate terminal compact_result messages and can omit the
 * opening status on replay. State therefore lives until the owning turn's
 * result (or abort), while a new compacting status after a terminal outcome
 * starts a fresh lifecycle.
 */
export class ContextCompactionLifecycle {
  private activeCompaction: CompactionState | undefined;
  private outputDelivered = false;
  private duplicateErrorOutput: string | undefined;
  /** After interruption, uncorrelated terminal frames and hooks may still
   *  arrive from the abandoned work, including an opening we never consumed.
   *  Wait for a known new turn before accepting them again. */
  private interrupted = false;
  /** Summary reported by PostCompact before the opening status was consumed.
   *  Deliberately survives `reset()`: the CLI awaits the hook before emitting
   *  the compaction's terminal frames, so a pending summary always belongs to
   *  a compaction whose frames are still ahead of the consumer — possibly
   *  queued behind a previous turn's result. */
  private pendingSummary: string | undefined;
  private readonly sessionId: string;
  readonly presentation: CompactionPresentation;
  private readonly logError: (message: string, error: unknown) => void;

  constructor(
    private readonly sendUpdate: SendUpdate,
    options: ContextCompactionLifecycleOptions,
  ) {
    this.sessionId = options.sessionId;
    this.presentation = options.presentation ?? "tool_call";
    this.logError = options.logError ?? (() => {});
  }

  get hasDeliveredOutput(): boolean {
    return this.outputDelivered;
  }

  /**
   * Close the lifecycle at a turn boundary (result, cancel, idle-abandon).
   *
   * A `compaction_update` entity still `in_progress` here never received its
   * terminal signal from the runtime and gets its one terminal status,
   * `cancelled`. The legacy tool call is deliberately left as it was (an
   * `in_progress` call): ACP `ToolCallStatus` has no cancelled state and that
   * presentation's behavior predates this lifecycle. Never throws — a failed
   * send is logged, so callers can settle the turn unconditionally.
   */
  async reset(): Promise<void> {
    const state = this.activeCompaction;
    this.activeCompaction = undefined;
    this.outputDelivered = false;
    this.duplicateErrorOutput = undefined;
    if (!state || state.terminalStatus || this.presentation !== "compaction_update") return;
    state.terminalStatus = "cancelled";
    await this.sendQuietly(
      {
        sessionUpdate: "compaction_update",
        compactionId: state.compactionId,
        status: "cancelled",
      },
      "cancelled compaction",
    );
  }

  /** Abandon the current work before settling its prompt or tearing down the
   *  stream. Unlike a normal result boundary, its pending hooks are not safe
   *  to carry into the next compaction. A hook has no command ID, so even an
   *  early hook for the next compaction must be omitted until the stream gives
   *  us a new live turn boundary. Idempotent and best-effort. */
  async interrupt(): Promise<void> {
    if (this.presentation === "compaction_update") {
      this.interrupted = true;
      this.pendingSummary = undefined;
    }
    await this.reset();
  }

  /** A live command's dispatch/echo proves the interrupted command's tail
   *  has drained in the SDK's FIFO stream. Do not reset normal lifecycle
   *  state: compaction may already have started before the user echo. */
  resume(): void {
    this.interrupted = false;
  }

  /**
   * Claude also emits a failed manual compaction's error as local-command
   * stdout. Consume that one duplicate after the lifecycle carried it,
   * without hiding unrelated command output.
   */
  consumeDuplicateErrorOutput(content: string): boolean {
    if (
      this.duplicateErrorOutput === undefined ||
      content.trim() !== this.duplicateErrorOutput.trim()
    ) {
      return false;
    }
    this.duplicateErrorOutput = undefined;
    return true;
  }

  async start(compactionId: string): Promise<void> {
    if (this.interrupted) return;
    if (this.activeCompaction && !this.activeCompaction.terminalStatus) {
      return;
    }

    this.open(compactionId);
    if (this.presentation === "compaction_update") {
      await this.send({
        sessionUpdate: "compaction_update",
        compactionId,
        status: "in_progress",
        _meta: createContextCompactionMeta(),
      });
      return;
    }
    await this.send({
      sessionUpdate: "tool_call",
      toolCallId: compactionId,
      title: "Compact conversation",
      kind: "think",
      status: "in_progress",
      _meta: compactionToolMeta(),
    });
  }

  /**
   * Streaming progress from the API's compaction content block.
   *
   * Under `compaction_update` the block's text is the retained summary and
   * streams as `compaction_summary_chunk`s — but only into an entity the CLI
   * announced with its `compacting` status. The block alone carries no
   * terminal signal, so opening an entity from it would leave nothing but the
   * turn-boundary `cancelled` to close a compaction that succeeded. The legacy
   * tool call keeps its historical behavior: open on first sight, re-assert
   * `in_progress` once.
   */
  async heartbeat(fallbackId: string, summaryChunk?: string): Promise<void> {
    if (this.presentation === "compaction_update") {
      const state = this.activeCompaction;
      if (!state || state.terminalStatus || !summaryChunk) return;
      await this.send({
        sessionUpdate: "compaction_summary_chunk",
        compactionId: state.compactionId,
        content: { type: "text", text: summaryChunk },
      });
      return;
    }

    if (!this.activeCompaction) await this.start(fallbackId);
    const state = this.activeCompaction;
    if (!state || state.terminalStatus || state.heartbeatSent) return;
    state.heartbeatSent = true;
    await this.send({
      sessionUpdate: "tool_call_update",
      toolCallId: state.compactionId,
      status: "in_progress",
      _meta: compactionToolMeta(),
    });
  }

  /**
   * The PostCompact hook's summary. The CLI awaits the hook before emitting
   * the compaction's terminal frames, so the summary lands while its
   * compaction is `in_progress` and rides on the terminal update. Anything
   * else — no entity yet, or the entity is a previous, already-terminal
   * compaction of the same turn whose status frame the consumer is still
   * catching up to — belongs to the compaction whose frames are ahead of the
   * consumer, and waits for it. Only the `compaction_update` presentation
   * carries the summary; the legacy tool call never exposed it. Never throws:
   * it runs detached from a hook callback. Returns whether a summary was
   * retained.
   */
  recordSummary(rawSummary: unknown): boolean {
    if (this.interrupted) return false;
    if (this.presentation !== "compaction_update" || typeof rawSummary !== "string") return false;
    const summary = compactionSummaryText(rawSummary);
    if (!summary) return false;

    const state = this.activeCompaction;
    if (state && !state.terminalStatus) {
      state.summary = summary;
    } else {
      this.pendingSummary = summary;
    }
    return true;
  }

  async finish(
    compactionId: string,
    status: CompactionStatus,
    metadata: Omit<ContextCompactionMetadata, "version"> = {},
    enrichTerminal = false,
  ): Promise<void> {
    if (this.interrupted) return;
    // The opening status can be missed (replay, or a terminal-only runtime):
    // the first update for the ID is then already terminal.
    const opened = this.activeCompaction === undefined;
    const firstTerminal = !this.activeCompaction?.terminalStatus;
    const state = this.activeCompaction ?? this.open(compactionId, status);
    if (firstTerminal) {
      state.terminalStatus = status;
    } else if (!enrichTerminal) {
      return;
    }
    if (status === "failed" && metadata.error) {
      this.duplicateErrorOutput = metadata.error;
    }
    const terminalStatus = state.terminalStatus ?? status;
    const hasMetadata = Object.keys(metadata).length > 0;

    if (this.presentation === "compaction_update") {
      const summary = firstTerminal && terminalStatus === "completed" ? state.summary : undefined;
      await this.send({
        sessionUpdate: "compaction_update",
        compactionId: state.compactionId,
        status: terminalStatus,
        ...(summary !== undefined ? { summary: [{ type: "text", text: summary }] } : {}),
        ...(terminalStatus === "failed" && metadata.error ? { error: metadata.error } : {}),
        // `_meta` is a replace-patch: seed it with the first terminal, then
        // only re-send it when the boundary adds facts, so a status-only
        // duplicate can't wipe the token counts.
        ...(firstTerminal || hasMetadata ? { _meta: createContextCompactionMeta(metadata) } : {}),
      });
      return;
    }

    const rawOutput = hasMetadata ? metadata : undefined;
    const errorContent =
      status === "failed" && metadata.error
        ? { content: [compactionErrorContent(metadata.error)] }
        : {};
    if (opened) {
      await this.send({
        sessionUpdate: "tool_call",
        toolCallId: state.compactionId,
        title: "Compact conversation",
        kind: "think",
        status,
        ...errorContent,
        ...(rawOutput ? { rawOutput } : {}),
        _meta: compactionToolMeta(metadata),
      });
      return;
    }
    await this.send({
      sessionUpdate: "tool_call_update",
      toolCallId: state.compactionId,
      ...(firstTerminal ? { status } : {}),
      ...errorContent,
      ...(rawOutput ? { rawOutput } : {}),
      _meta: compactionToolMeta(metadata),
    });
  }

  /** Make `compactionId` the active entity, moving a pending hook summary onto
   *  it, and mark compaction output as delivered for the owning turn. */
  private open(compactionId: string, terminalStatus?: TerminalStatus): CompactionState {
    const state: CompactionState = {
      compactionId,
      heartbeatSent: false,
      ...(terminalStatus ? { terminalStatus } : {}),
      ...(this.pendingSummary !== undefined ? { summary: this.pendingSummary } : {}),
    };
    this.pendingSummary = undefined;
    this.activeCompaction = state;
    this.outputDelivered = true;
    return state;
  }

  private send(update: SessionNotification["update"]): Promise<void> {
    return this.sendUpdate({ sessionId: this.sessionId, update });
  }

  private async sendQuietly(update: SessionNotification["update"], what: string): Promise<void> {
    try {
      await this.send(update);
    } catch (error) {
      this.logError(`Failed to send the ${what} update for session ${this.sessionId}`, error);
    }
  }
}

export function contextCompactionMetadataFromBoundary(compactMetadata: {
  trigger: "manual" | "auto";
  pre_tokens: number;
  post_tokens?: number;
  duration_ms?: number;
}): Omit<ContextCompactionMetadata, "version"> {
  return {
    trigger: compactMetadata.trigger === "auto" ? "automatic" : "manual",
    preTokens: compactMetadata.pre_tokens,
    ...(compactMetadata.post_tokens !== undefined
      ? { postTokens: compactMetadata.post_tokens }
      : {}),
    ...(compactMetadata.duration_ms !== undefined
      ? { durationMs: compactMetadata.duration_ms }
      : {}),
  };
}

function compactionToolMeta(
  metadata: Omit<ContextCompactionMetadata, "version"> = {},
): Record<string, unknown> {
  return {
    ...createContextCompactionMeta(metadata),
    claudeCode: { toolName: "compact" },
  };
}

function compactionErrorContent(error: string) {
  return {
    type: "content" as const,
    content: {
      type: "text" as const,
      text: `Compaction failed: ${error}`,
    },
  };
}

/**
 * `authStatus` — interim `_meta`-based ACP extension that reports which auth
 * identity the agent process itself uses (Claude subscription, API key,
 * gateway, external cloud credentials, or nothing).
 *
 * Push only. One carrier, connection-scoped (never per session): the
 * notification `_auth/status_update` → `{authStatus}`. The client never asks;
 * there is no request method. The empty `agentCapabilities._meta.authStatus`
 * marker means "this agent pushes its identity", nothing more.
 *
 * The agent reads the identity at these moments:
 * - `initialize`, with an asynchronous CLI probe. Nothing waits for it, and its
 *   result is the first push of the connection;
 * - a completed `authenticate` or a `logout`;
 * - each `createSession`, from the session account. A refused session reports
 *   too: the client must know which account was refused;
 * - each turn the `--hide-claude-auth` guard checks. The guard reads the
 *   account anyway, so this costs nothing;
 * - the START of each user prompt, with an asynchronous CLI probe. This finds a
 *   login or a logout done in another terminal, including the sign-in a client
 *   performs after a refusal, because the retried prompt is a new prompt.
 *   Nothing waits for it and the push goes out mid-turn if that is when the
 *   read lands.
 *
 * A probe whose kind differs from a live session's account marks that session
 * for recreation under `--hide-claude-auth`. The mark is a flag, consumed at
 * the next turn boundary: a running turn is never interrupted. The probe judges
 * nothing itself — the next turn runs a new `initialize`, and the creation
 * guard decides on the account it reports.
 *
 * A read does not always cause a push. The agent sends `_auth/status_update`
 * only when the payload is different from the last one it sent.
 *
 * "Cannot determine" is expressed by silence: an agent that cannot read its own
 * identity pushes nothing, and the client shows "not reported". A known
 * logged-out state is a payload of its own (`kind: "none"`), which is what
 * distinguishes the two.
 *
 * Reporting only — there is no write path in v1. When the upstream RFD lands,
 * the same payload moves from `_meta` to first-class fields and this module
 * is retired.
 */

import type { AccountInfo } from "@anthropic-ai/claude-agent-sdk";

/** Change notification, agent → client. Fire and forget: clients that do not
 *  know the method drop it silently, so it is sent unconditionally. */
export const AUTH_STATUS_UPDATE_METHOD = "_auth/status_update";

/** Upper bound on one `claude auth status --json` run, so a hung CLI cannot
 *  wedge every later probe that joins it. */
export const AUTH_STATUS_PROBE_TIMEOUT_MS = 5000;

export type AuthStatusKind = "account" | "api_key" | "gateway" | "external" | "none";

export type AuthStatusAccount = {
  email?: string;
  organization?: string;
  /** Vendor plan/license string, not normalized. */
  plan?: string;
};

export type AuthStatus = {
  kind: AuthStatusKind;
  /** Human-readable and usable as a UI string on its own. The "type" line:
   *  "Claude Max", "Anthropic API key", "AWS Bedrock". */
  label: string;
  /** Optional second line carrying the specifics (key source, gateway host, …).
   *  Clients render it under `label`, falling back to `account.email`. */
  detail?: string;
  account?: AuthStatusAccount;
  /** Vendor-namespaced extras, e.g. `{claudeCode: {...}}`. */
  vendor?: Record<string, unknown>;
};

export type AuthStatusUpdateNotification = { authStatus: AuthStatus };

/** Advertisement carried in `agentCapabilities._meta.authStatus`, never a
 *  status payload: its mere presence means "this agent pushes its identity",
 *  and it stays empty. Informational — a client that never saw it still
 *  accepts `_auth/status_update`, because there is nothing to ask for. */
export type AuthStatusCapability = Record<string, never>;

export function authStatusCapability(): AuthStatusCapability {
  return {};
}

/** Shape of `claude auth status --json`. Absent fields are omitted, not null,
 *  and the logged-out case exits 1 while still printing valid JSON. */
export type CliAuthStatus = {
  loggedIn?: boolean;
  authMethod?: string;
  apiProvider?: string;
  apiKeySource?: string;
  email?: string;
  orgId?: string;
  orgName?: string;
  subscriptionType?: string;
};

const NOT_LOGGED_IN: AuthStatus = {
  kind: "none",
  label: "Not logged in",
};

/** Display names for the non-firstParty backends, where auth lives outside the
 *  agent (AWS credentials, gcloud ADC, …). */
const EXTERNAL_PROVIDER_LABELS: Record<string, string> = {
  bedrock: "AWS Bedrock",
  vertex: "Google Vertex AI",
  foundry: "Azure AI Foundry",
  anthropicAws: "Anthropic on AWS",
  anthropicGoogleCloud: "Anthropic on Google Cloud",
  mantle: "Mantle",
};

export function notLoggedInAuthStatus(): AuthStatus {
  return { ...NOT_LOGGED_IN };
}

/** ACP-level gateway auth (`authenticate` with `gateway`/`gateway-bedrock`).
 *  The gateway owns the credentials, so it wins over anything the CLI reports. */
export function gatewayAuthStatus(baseUrl?: string): AuthStatus {
  let host: string | undefined;
  if (baseUrl) {
    try {
      host = new URL(baseUrl).host;
    } catch {
      host = baseUrl;
    }
  }
  return {
    kind: "gateway",
    label: "Custom model gateway",
    ...(host ? { detail: host } : {}),
  };
}

/**
 * Does this `AccountInfo` say anything about the identity?
 *
 * The SDK always fills `apiProvider`, but the identity fields come from the
 * claude.ai profile: with an `apiKeyHelper` and no subscription login the
 * session reports `{apiProvider: "firstParty"}` and nothing else. That is "no
 * information", not "logged out" — an empty read must never be mapped to
 * `none`, or it destroys what the CLI probe already established.
 *
 * `tokenSource` is deliberately not a signal: the CLI sets it to the OAuth
 * token's origin (`CLAUDE_CODE_OAUTH_TOKEN`,
 * `CLAUDE_CODE_OAUTH_TOKEN_FILE_DESCRIPTOR`, …), never to a key source, so it
 * cannot attribute a key and carries no plan of its own.
 */
export function accountInfoHasIdentitySignal(account: AccountInfo | undefined): boolean {
  if (!account) return false;
  return Boolean(
    account.apiKeySource ||
    account.subscriptionType ||
    (account.apiProvider && account.apiProvider !== "firstParty"),
  );
}

/** Session-time mapping from the SDK's `AccountInfo`, the richest source when
 *  it is populated. Returns `undefined` when the account carries no identity
 *  signal, so callers keep the status they already know. */
export function fromAccountInfo(account: AccountInfo | undefined): AuthStatus | undefined {
  if (!account || !accountInfoHasIdentitySignal(account)) {
    return undefined;
  }
  return mapAuthFields({
    apiProvider: account.apiProvider,
    subscriptionType: account.subscriptionType,
    apiKeySource: account.apiKeySource,
    email: account.email,
    organization: account.organization,
  });
}

/** Pre-session mapping from `claude auth status --json` stdout. Returns
 *  `undefined` when the output is not the expected JSON object, so callers can
 *  report "not known" instead of guessing. */
export function fromCliStatus(stdout: string): AuthStatus | undefined {
  let parsed: unknown;
  try {
    parsed = JSON.parse(stdout);
  } catch {
    return undefined;
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    return undefined;
  }
  const status = parsed as CliAuthStatus;
  if (typeof status.loggedIn !== "boolean") {
    return undefined;
  }
  // `loggedIn` tracks the claude.ai login only. On a 3P backend (Bedrock,
  // Vertex, …) it is false while the credentials live outside the agent, so the
  // backend must decide the kind before the logged-out shortcut runs.
  const externalBackend = Boolean(status.apiProvider && status.apiProvider !== "firstParty");
  if (!externalBackend && !status.loggedIn && !status.apiKeySource) {
    return notLoggedInAuthStatus();
  }
  return mapAuthFields({
    apiProvider: status.apiProvider,
    subscriptionType: status.subscriptionType,
    apiKeySource: status.apiKeySource,
    email: status.email,
    organization: status.orgName,
  });
}

/** Single mapping table shared by both sources; see the `kind`/`label` table in
 *  `extension-authstatus-meta.md`. Order matters: a 3P backend or a gateway
 *  decides the kind before any firstParty identity fields are considered, and
 *  an API key outranks a stored subscription login.
 *
 *  Both can be reported at once — an `apiKeyHelper` in settings.json next to a
 *  claude.ai OAuth login yields `apiKeySource` AND `subscriptionType`. Claude
 *  Code's authentication precedence puts `apiKeyHelper` above the `/login`
 *  subscription, so the key is what actually pays for the turn and is what we
 *  report. */
function mapAuthFields(fields: {
  apiProvider?: string;
  subscriptionType?: string;
  apiKeySource?: string;
  email?: string;
  organization?: string;
}): AuthStatus {
  const { apiProvider, subscriptionType, apiKeySource, email, organization } = fields;

  if (apiProvider === "gateway") {
    return gatewayAuthStatus();
  }
  if (apiProvider && apiProvider !== "firstParty") {
    return {
      kind: "external",
      label: EXTERNAL_PROVIDER_LABELS[apiProvider] ?? apiProvider,
    };
  }
  if (apiKeySource) {
    return {
      kind: "api_key",
      label: "Anthropic API key",
      // The source ("apiKeyHelper", "env", …) is the specifics line.
      detail: apiKeySource,
    };
  }
  if (subscriptionType) {
    // `account.plan` keeps the raw vendor string; only the label is titled.
    const account: AuthStatusAccount = { plan: subscriptionType };
    if (email) account.email = email;
    if (organization) account.organization = organization;
    return {
      kind: "account",
      label: planLabel(subscriptionType),
      // No detail: the client falls back to `account.email` for line 2.
      account,
    };
  }
  return notLoggedInAuthStatus();
}

/** Names the plan with exactly one "Claude". A newer CLI already reports
 *  "Claude Max", an older one reports "max", and both must read "Claude Max".
 *  Each word is title-cased; a word that already carries capitals is kept. */
function planLabel(plan: string): string {
  const titled = plan.replace(/\S+/g, (word) => word.charAt(0).toUpperCase() + word.slice(1));
  return /^claude(\s|$)/i.test(plan) ? titled : `Claude ${titled}`;
}

/**
 * Do two payloads describe the same login? Compared on the field that
 * identifies each kind — the key source for `api_key`, the email for
 * `account`, the kind alone for the rest, which carry no per-identity key.
 */
export function sameIdentity(a: AuthStatus, b: AuthStatus): boolean {
  if (a.kind !== b.kind) {
    return false;
  }
  switch (a.kind) {
    case "api_key":
      return a.detail === b.detail;
    case "account":
      return (a.account?.email ?? "") === (b.account?.email ?? "");
    default:
      return true;
  }
}

/**
 * Folds a fresh read into what is already known. Sources differ in richness for
 * the very same login: the SDK's session `AccountInfo` can carry an
 * organization the CLI probe omits. So when the read describes the same
 * identity, its values win field by field but the fields it lacks are kept;
 * when it describes a different identity, it replaces the old one wholesale.
 */
export function mergeAuthStatus(previous: AuthStatus | undefined, next: AuthStatus): AuthStatus {
  if (!previous || !sameIdentity(previous, next)) {
    return next;
  }
  const merged: AuthStatus = { ...next };
  if (merged.detail === undefined && previous.detail !== undefined) {
    merged.detail = previous.detail;
  }
  if (previous.account || next.account) {
    merged.account = { ...previous.account, ...next.account };
  }
  if (merged.vendor === undefined && previous.vendor !== undefined) {
    merged.vendor = previous.vendor;
  }
  return merged;
}

/**
 * Do two payloads carry the same information? Unlike {@link sameIdentity},
 * which asks "is this the same login", this compares every rendered field, so
 * a richer read of one login is NOT the same. Callers use it to suppress a
 * push that would tell the client nothing new.
 *
 * `a` undefined means "nothing reported yet", which never equals a payload.
 */
export function sameAuthStatus(a: AuthStatus | undefined, b: AuthStatus): boolean {
  if (!a) {
    return false;
  }
  return (
    a.kind === b.kind &&
    a.label === b.label &&
    a.detail === b.detail &&
    a.account?.email === b.account?.email &&
    a.account?.organization === b.account?.organization &&
    a.account?.plan === b.account?.plan &&
    // Vendor extras are an open bag, so compare them structurally. Both sides
    // are built by this module from the same key order, so a string compare is
    // enough and costs nothing on the usual `undefined`/`undefined` pair.
    JSON.stringify(a.vendor) === JSON.stringify(b.vendor)
  );
}

/**
 * `--hide-claude-auth`: this integration must never bill a claude.ai
 * subscription. The flag hides the claude.ai login method from `initialize`
 * and makes the agent behave like a logged-out CLI whenever a subscription
 * would pay for a turn. `acp-agent.ts` decides *when* the guard applies (flag
 * on, no provider override) and calls in here for the *what*.
 *
 * The account the CLI reports at `initialize` is the source of truth. The SDK
 * memoizes it, so it is a constant for the life of a query, and two layers
 * keep it honest:
 *
 * 1. Session creation refuses an account that holds no credential this
 *    integration accepts. A logged-out session never exists, so the client's
 *    sign-in always leads to a new session with a fresh `initialize`. The
 *    per-turn guard repeats the check on the same cached account, which costs
 *    microseconds and covers a session created under a provider override that
 *    `providers/disable` later removed.
 * 2. A sign-out during the session ends the query. The next turn recreates it,
 *    so the next `initialize` reports the real account and layer 1 judges it.
 *    The recreation resumes the stored conversation. When the CLI never wrote
 *    one, because the first turn was the one that signed out, the recreation
 *    starts a fresh query under the same session id instead.
 *
 * A file-based credential replaced by a subscription between two turns is seen
 * by the CLI probe the agent fires at the START of every user prompt. That read
 * is never awaited, so it usually lands mid-turn; all it does there is mark the
 * session. The guard consumes the mark at the turn boundary — the next prompt
 * recreates the query and layer 1 judges the account the new `initialize`
 * reports — so a probe never interrupts a running turn. A swap that happens
 * after the last probe stays unseen until the next prompt reads the store
 * again. Closing that window would cost a blocking read per turn.
 */

import { RequestError } from "@agentclientprotocol/sdk";
import type { AccountInfo, Query } from "@anthropic-ai/claude-agent-sdk";
import type { SessionFailureController } from "./session-failure-extension.js";

export function shouldHideClaudeAuth(): boolean {
  return process.argv.includes("--hide-claude-auth");
}

/**
 * `data.reason` carried by the `authRequired` JSON-RPC error when the flag
 * blocks a turn. From the client's point of view the agent is logged out (same
 * error code and flow as a signed-out CLI); the reason lets it render a
 * different hint. A string enum so further reasons can be added without a
 * shape change.
 */
export const CLAUDE_SUBSCRIPTION_NOT_SUPPORTED_REASON = "claude_subscription_not_supported";
export type AuthRequiredReason = typeof CLAUDE_SUBSCRIPTION_NOT_SUPPORTED_REASON;

export const CLAUDE_SUBSCRIPTION_NOT_SUPPORTED_MESSAGE =
  "This integration does not support using claude.ai subscriptions.";

/** The message of the plain sign-out refusal. It carries no `reason`: the
 *  account holds nothing this integration can bill, which is the ordinary
 *  signed-out state every ACP client already knows how to answer. */
export const CLAUDE_LOGIN_REQUIRED_MESSAGE =
  "Sign in with an API key or a Console account to use this integration.";

/**
 * The `apiKeySource` values that outrank a stored subscription.
 *
 * The SDK documents its `ApiKeySource` type as the origin of the credential
 * used for API requests. `ANTHROPIC_API_KEY` is the environment variable,
 * `apiKeyHelper` is the configured helper command, and `/login managed key` is
 * a key that `/login` created with an Anthropic Console account. Each of the
 * three is an API key that pays instead of the subscription. Every other
 * member means no API key is in use: `none`, and the legacy `user`, `project`,
 * `org`, `temporary` and `oauth` that current CLIs never emit.
 */
const API_KEY_SOURCES_ABOVE_SUBSCRIPTION: ReadonlySet<string> = new Set([
  "ANTHROPIC_API_KEY",
  "apiKeyHelper",
  "/login managed key",
]);

/**
 * True when a turn on this account is paid by a claude.ai subscription.
 *
 * The SDK types `apiKeySource` and `tokenSource` as an open `string`, so this
 * is an allowlist. An account bills the subscription only when every field
 * proves it, and an unknown value keeps the guard on.
 *
 * - `subscriptionType` must be set. Without it the CLI reports no subscription.
 * - `tokenSource` must be absent. The CLI sets it in place of the subscription
 *   when a bearer or OAuth environment token pays for the turn.
 * - `apiProvider` must be absent or `firstParty`. The SDK documents that the
 *   Anthropic OAuth login applies only to `firstParty`; for a third-party
 *   backend such as `bedrock`, `vertex`, `foundry` or `gateway` the other
 *   fields are absent and the authentication is external.
 * - `apiKeySource` must not be one of {@link API_KEY_SOURCES_ABOVE_SUBSCRIPTION}.
 *   Claude Code's credential precedence puts those keys above the `/login`
 *   subscription, so the key pays and the stored subscription is inert.
 */
export function billsClaudeSubscription(account: AccountInfo | undefined): boolean {
  if (!account?.subscriptionType) {
    return false;
  }
  if (account.tokenSource) {
    return false;
  }
  if (account.apiProvider !== undefined && account.apiProvider !== "firstParty") {
    return false;
  }
  return !API_KEY_SOURCES_ABOVE_SUBSCRIPTION.has(account.apiKeySource ?? "");
}

/**
 * True when the account already holds a credential this integration accepts:
 * a third-party backend, a bearer or OAuth environment token, or one of the
 * API key sources in {@link API_KEY_SOURCES_ABOVE_SUBSCRIPTION}.
 *
 * False therefore covers both the signed-out CLI and the account whose only
 * credential is a claude.ai subscription. {@link billsClaudeSubscription} runs
 * first and separates the two, so a caller that reaches a `false` here is
 * looking at a session with no way to pay.
 */
export function holdsNonSubscriptionCredential(account: AccountInfo | undefined): boolean {
  if (!account) {
    return false;
  }
  if (account.apiProvider !== undefined && account.apiProvider !== "firstParty") {
    return true;
  }
  if (account.tokenSource) {
    return true;
  }
  return API_KEY_SOURCES_ABOVE_SUBSCRIPTION.has(account.apiKeySource ?? "");
}

export function claudeSubscriptionNotSupportedError(): RequestError {
  return RequestError.authRequired(
    { reason: CLAUDE_SUBSCRIPTION_NOT_SUPPORTED_REASON satisfies AuthRequiredReason },
    CLAUDE_SUBSCRIPTION_NOT_SUPPORTED_MESSAGE,
  );
}

/** The signed-out refusal. Deliberately without `data`, so a client that reads
 *  `data.reason` sees the plain ACP sign-out it already handles. */
export function claudeLoginRequiredError(): RequestError {
  return RequestError.authRequired(undefined, CLAUDE_LOGIN_REQUIRED_MESSAGE);
}

/**
 * The state the guard keeps for one session. It lives on the session so that a
 * concurrent pair of turns shares one account read and one failure row, and so
 * that each degraded-guard warning is logged once.
 */
export type ClaudeSubscriptionGuardState = {
  /** The in-flight guard run. Set before the first `await`. */
  pendingRun?: Promise<RequestError | undefined>;
  /** True after the "no account source" warning was logged for this session. */
  degradedWarningLogged?: boolean;
};

export type GuardLogger = {
  error: (...args: unknown[]) => void;
  warn?: (...args: unknown[]) => void;
};

function warn(logger: GuardLogger, message: string): void {
  (logger.warn ?? logger.error).call(logger, message);
}

/**
 * Report once per session that the guard cannot read the account at all. The
 * guard is then absent, not passing. The CLI build decides this, not the user,
 * so a message on every turn would only add noise.
 */
export function warnClaudeSubscriptionGuardDegraded(options: {
  sessionId: string;
  guardState: ClaudeSubscriptionGuardState;
  logger: GuardLogger;
  cause: string;
}): void {
  const { guardState } = options;
  if (guardState.degradedWarningLogged) {
    return;
  }
  guardState.degradedWarningLogged = true;
  warn(
    options.logger,
    `Session ${options.sessionId}: the --hide-claude-auth subscription guard is degraded ` +
      `(${options.cause}). This session cannot detect a claude.ai subscription.`,
  );
}

type GuardOptions = {
  sessionId: string;
  query: Pick<Query, "accountInfo">;
  guardState: ClaudeSubscriptionGuardState;
  /** Built lazily: most turns pass and never need a controller. */
  sessionFailures: () => SessionFailureController;
  logger: GuardLogger;
  /** Display hook: called with the account the guard just read, before the
   *  guard decides on it. It exists so a refused turn still reports which
   *  account it was refused for. Purely observational — this module knows
   *  nothing about what the caller does with it, and a throw from here never
   *  changes the verdict. */
  onAccount?: (account: AccountInfo) => void;
};

/**
 * The per-turn guard for a live session.
 *
 * It decides on the account the SDK cached at `initialize`, which is this
 * integration's source of truth. That account is a constant for the life of
 * the query, so the check costs microseconds. It still earns its place: it
 * covers a session created under a provider override that `providers/disable`
 * later removed, so the create-time check never ran for the routing in force
 * now. A sign-out ends the query (see `markSessionForSignOutRespawn` in
 * `acp-agent.ts`), so the next turn recreates it and `initialize` reports the
 * real account. This guard does not see the residual case the module header
 * names either.
 *
 * A turn is refused when the account bills a subscription, and also when it
 * holds nothing this integration accepts, which is the user signing out in
 * mid-session. The refusal mirrors the signed-out path exactly (see
 * `failActiveWithSessionFailure` for `auth_required` in `acp-agent.ts`): every
 * client gets the `authRequired` JSON-RPC rejection that starts its own auth
 * flow, and a capable client additionally gets one session-scoped access
 * failure whose `login` action stays the way back in.
 *
 * Fails open when no account can be read at all: session creation already
 * refused every account without a usable credential, and an unavailable probe
 * must not block a session that passed that check.
 */
export async function refuseClaudeSubscriptionTurn(options: GuardOptions): Promise<void> {
  // Concurrent turns must not each re-read the account and each publish a row.
  // Store the run before the first await, and let the others await the same one.
  const { guardState } = options;
  const run = (guardState.pendingRun ??= evaluateGuard(options).finally(() => {
    if (guardState.pendingRun === run) {
      guardState.pendingRun = undefined;
    }
  }));
  const refusal = await run;
  if (refusal) {
    throw refusal;
  }
}

/** Read the account, publish at most one failure row, and return the error the
 *  turn must be rejected with. Never throws: an unreadable account fails open. */
async function evaluateGuard(options: GuardOptions): Promise<RequestError | undefined> {
  const account = await readGuardAccount(options);
  if (!account) {
    return undefined;
  }
  // Before the decision, so the client learns the identity even when the next
  // lines refuse the turn. A display hook must never fail a guard.
  try {
    options.onAccount?.(account);
  } catch (error) {
    options.logger.error(
      `Session ${options.sessionId}: the guard's onAccount hook threw:`,
      error instanceof Error ? error.message : String(error),
    );
  }
  if (billsClaudeSubscription(account)) {
    await publishRefusal(options.sessionFailures(), {
      details: CLAUDE_SUBSCRIPTION_NOT_SUPPORTED_MESSAGE,
      reason: CLAUDE_SUBSCRIPTION_NOT_SUPPORTED_REASON,
    });
    return claudeSubscriptionNotSupportedError();
  }
  if (!holdsNonSubscriptionCredential(account)) {
    await publishRefusal(options.sessionFailures(), { details: CLAUDE_LOGIN_REQUIRED_MESSAGE });
    return claudeLoginRequiredError();
  }
  return undefined;
}

/** The account the SDK cached at `initialize`. `undefined` when the query
 *  cannot answer at all. */
async function readGuardAccount(options: GuardOptions): Promise<AccountInfo | undefined> {
  const { query } = options;
  if (typeof query.accountInfo !== "function") {
    warnClaudeSubscriptionGuardDegraded({
      ...options,
      cause: "the SDK query has no accountInfo method",
    });
    return undefined;
  }
  try {
    return await query.accountInfo();
  } catch (error) {
    options.logger.error(
      `Session ${options.sessionId}: accountInfo failed; skipping the subscription check for this turn:`,
      error instanceof Error ? error.message : String(error),
    );
    return undefined;
  }
}

/** The refusal state does not change between turns: publish once, and skip a
 *  republish while the previous failure with this reason is still active. */
async function publishRefusal(
  sessionFailures: SessionFailureController,
  failure: { details: string; reason?: string },
): Promise<void> {
  if (sessionFailures.hasActiveSessionError("auth_required", failure.reason)) {
    return;
  }
  await sessionFailures.publish("auth_required", {
    sessionScoped: true,
    details: failure.details,
    ...(failure.reason ? { reason: failure.reason } : {}),
  });
}

import type { RequestPermissionResponse } from "@agentclientprotocol/sdk";
import type { PermissionOption } from "@agentclientprotocol/sdk";
import type { PermissionMode, PermissionResult } from "@anthropic-ai/claude-agent-sdk";
import type { DurablePermissionChangeSet } from "./normalization.js";
import { applyClaudePermissionSelection, parseClaudePermissionSelection } from "./effects.js";

export interface ClaudePermissionDecision {
  permissionResult: PermissionResult;
  contextResetMode?: PermissionMode;
}

/** Decode, validate, and interpret an ACP response exactly once. */
export function decodeClaudePermissionResponse(
  response: RequestPermissionResponse,
  toolName: string,
  input: Record<string, unknown>,
  toolUseID: string,
  offeredOptions: readonly PermissionOption[],
  durableChangeSet?: DurablePermissionChangeSet,
): ClaudePermissionDecision {
  const selection = parseClaudePermissionSelection(response, toolName);
  const offeredOption = offeredOptions.find((option) => option.optionId === selection.optionId);
  if (!offeredOption) {
    throw new Error(`Permission option was not offered: ${selection.optionId}`);
  }
  const permissionResult = applyClaudePermissionSelection(selection, {
    toolName,
    input,
    toolUseID,
    durableChangeSet,
  });
  return {
    permissionResult,
    ...(selection.contextResetMode ? { contextResetMode: selection.contextResetMode } : {}),
  };
}
